const $=id=>document.getElementById(id);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
// Selected chronological exhibits. Cabinet studies share geometry, not exact component layouts.
const amps=[
 {"year": 1958, "name": "Tweed Champ", "era": "The tweed years", "years": "1958–1964, 8-inch version", "watts": 5, "speakers": "1 × 8″", "load": "4 Ω", "finish": "tweed", "width": 0.675, "height": 0.716, "circuit": "5F1", "voice": "One knob. A very direct conversation.", "story": "The eight-inch tweed Champ puts a single 6V6 power tube behind one switched Volume control. There is no separate tone stack or master volume to work around: the guitar and that one knob do the shaping. This entry follows the catalog’s 1958 start for the eight-inch version; the exterior study uses a photographed 1959 example.", "ratingNote": "Nominal load follows the catalog’s 4 Ω; vintage speakers may be marked 3.2 Ω."},
 {"year": 1955, "name": "Tweed Tremolux", "era": "The tweed years", "years": "1955–1957, 5E9 / 5E9-A", "watts": 15, "speakers": "1 × 12″", "load": "8 Ω", "finish": "tweed", "width": 1, "height": 0.955, "circuit": "5E9", "voice": "The small tweed gets a pulse.", "story": "The early Tremolux takes the small two-channel tweed format and adds Speed and Depth controls for tremolo. A pair of 6V6s and a single twelve keep it in the Deluxe’s neighborhood, but the five-knob top panel makes its extra trick visible. This is an early 1955 5E9 small-box study, not the later large-cabinet 5G9 or blonde piggyback.", "ratingNote": "15 W follows the selected catalog row; later versions and published ratings vary. Cabinet dimensions remain provisional."},
 {"year": 1961, "name": "Brown Deluxe", "era": "Brown & blonde", "years": "1961–1963", "watts": 20, "speakers": "1 × 12″", "load": "8 Ω", "finish": "brown", "width": 1.05, "height": 1.015, "circuit": "6G3", "voice": "A different kind of Deluxe bite.", "story": "The brown Deluxe gives each channel its own Volume and Tone, then adds tremolo without adding reverb. Its front-facing six-control panel sits in a cabinet narrower than the later Deluxe Reverb. This 1962 exterior study follows a Normal-left, Bright-right example, with brown barrel knobs and no badge on the grille.", "ratingNote": "20 W follows the catalog’s approximate rating; some references quote 15 W. Speaker construction and internal placement are illustrative."},
 {year:1946,name:'Woodie Deluxe',era:'The woodie years',years:'1946–1948',watts:12,speakers:'1 × 10″',load:'8 Ω',finish:'wood',width:.86,height:.91,circuit:'Model 26',voice:'An amplifier before the icon.',story:'The Model 26 belonged to Fender’s first generation of amplifiers. Its wooden cabinet and simple controls reflected an instrument still finding its form. The Deluxe name would endure as the cabinets, circuits and demands of working musicians evolved.'},
 {year:1949,name:'Champion 600',era:'The student years',years:'1949–1953',watts:4,speakers:'1 × 6″',load:'4 Ω',finish:'cream',width:.65,height:.72,circuit:'5B1 family',voice:'A small start to a loud story.',story:'The Champion 600 put a small tube amplifier within reach of beginning players. Its compact cabinet and six-inch speaker made it a distinctly personal instrument. Modest output would later become part of its appeal for players looking for small-amp character.'},
 {year:1953,name:'Wide-panel Deluxe',era:'The tweed years',years:'1953–1955',watts:12,speakers:'1 × 12″',load:'8 Ω',finish:'tweed',width:.94,height:.94,circuit:'5C3 / 5D3',voice:'The tweed story takes shape.',story:'Wide tweed panels framed the grille of this earlier Deluxe. Its evolving circuits bridged the first Fender combos and the celebrated narrow-panel generation. The combination of a single twelve-inch speaker and modest tube power was already becoming a lasting formula.'},
 {year:1955,name:'Tweed Deluxe',era:'The tweed years',years:'1955–1960',watts:12,speakers:'1 × 12″',load:'8 Ω',finish:'tweed',width:1,height:1,circuit:'5E3',voice:'The little amp that learned to roar.',full:true,story:'In 1955, Fender gave the Deluxe a narrow-panel cabinet and the 5E3 circuit—a modest amplifier built for working musicians. Its pair of 6V6 power tubes delivered warm cleans that gave way to thick, compressed overdrive as the volume climbed. Neil Young made the tweed Deluxe part of his unmistakable electric voice. The secret wasn’t more power: it was what happened when this small amp reached its limits.'},
 {year:1957,name:'High-power Twin',era:'The tweed years',years:'1957–1960',watts:80,speakers:'2 × 12″',load:'4 Ω',finish:'tweed',width:1.25,height:1.03,circuit:'5F8 / 5F8-A',voice:'Tweed, on a much bigger scale.',story:'The high-power Twin brought four output tubes and two twelve-inch speakers to Fender’s tweed lineup. It offered far more clean headroom than the smaller combos. Its scale made it a very different instrument from the Deluxe, even beneath a similar covering.'},
 {year:1958,name:'Tweed Bassman',era:'The tweed years',years:'1958–1960',watts:45,speakers:'4 × 10″',load:'2 Ω',finish:'tweed',width:1.12,height:1.18,circuit:'5F6-A',voice:'Built for bass. Adopted by guitar.',story:'The Bassman began as a partner for the electric bass, but guitarists found a powerful voice in it too. The late tweed version used four ten-inch speakers and an influential four-input circuit. Its reach extended well beyond Fender’s own amplifier family.'},
 {year:1961,name:'Brown Princeton',era:'Brown & blonde',years:'1961–1964',watts:12,speakers:'1 × 10″',load:'8 Ω',finish:'brown',width:.88,height:.88,circuit:'6G2',voice:'A new look. An intimate voice.',story:'Brown covering marked a new chapter for the Princeton. Its two 6V6 output tubes and bias tremolo made a compact package with a distinct feel. It sits between the small tweed Princeton and the later reverb-equipped designs.'},
 {year:1963,name:'Brown Vibroverb',era:'Brown & blonde',years:'1963',watts:35,speakers:'2 × 10″',load:'4 Ω',finish:'brown',width:1.15,height:1.02,circuit:'6G16',voice:'A new dimension in the cabinet.',story:'The brown Vibroverb brought onboard spring reverb to a Fender combo. Its two ten-inch speakers and tremolo combined with that new effect in a short-lived design. The name soon moved to a different black-panel configuration, making this original version a distinctive chapter.'},
 {year:1963,name:'Deluxe Reverb',era:'The black-panel years',years:'1963–1967',watts:22,speakers:'1 × 12″',load:'8 Ω',finish:'black',width:1.08,height:.96,circuit:'AB763',voice:'The club-sized classic.',story:'The Deluxe Reverb combined a single twelve-inch speaker with spring reverb and tremolo. Its output gave working guitarists a practical balance of clean sound and driven response. The design became one of Fender’s most enduring reference points.'},
 {year:1963,name:'Super Reverb',era:'The black-panel years',years:'1963–1967',watts:40,speakers:'4 × 10″',load:'2 Ω',finish:'black',width:1.18,height:1.25,circuit:'AB763',voice:'Four speakers. A wide-open sound.',story:'The Super Reverb put four ten-inch speakers beneath a black control panel. Reverb, tremolo and a larger tube power section made it a substantial stage amplifier. Its tall cabinet became a familiar silhouette in the Fender family.'},
 {year:1968,name:'Twin Reverb',era:'The silver-panel years',years:'1968–1976',watts:85,speakers:'2 × 12″',load:'4 Ω',finish:'silver',width:1.25,height:1.02,circuit:'Early silver-panel family',ratingNote:'Early silver-panel Twins are commonly rated 85 watts. Later versions in this era increased to 100 watts; the 1977 ultralinear version is a separate exhibit.',voice:'Room for the clean sound to grow.',story:'The silver-panel Twin Reverb carried Fender’s big clean-combo idea into another era. Two twelve-inch speakers and considerable output suited players seeking headroom. Ratings and circuitry changed during this period, so the exact production version matters.'},
 {year:1982,name:'Super Champ',era:'The Rivera years',years:'1982–1986',watts:18,speakers:'1 × 10″',load:'8 Ω',finish:'black',width:.76,height:.86,circuit:'Rivera-era tube',voice:'Small gets ambitious.',story:'The Super Champ packed tube power, reverb and a lead voice into a compact cabinet. It represented a new direction for Fender’s small amps in the early 1980s. Its name should not be confused with the later digital-preamp XD and X2 models.'},
 {year:1993,name:'Blues Deluxe',era:'A modern revival',years:'1993–1996',watts:40,speakers:'1 × 12″',load:'8 Ω',finish:'tweed',width:1.12,height:1.02,circuit:'Original Blues series',voice:'A working amp, dressed in tweed.',story:'The Blues Deluxe brought tweed styling to a modern clean-and-drive platform. A forty-watt power section and onboard spring reverb made it a different design from the vintage 5E3. It helped establish the direction that the Hot Rod family would develop.'},
 {year:1996,name:'Hot Rod Deluxe',era:'The working years',years:'1996–2010, early generations',watts:40,speakers:'1 × 12″',load:'8 Ω',finish:'black',width:1.12,height:1.02,circuit:'Hot Rod I–II',voice:'Made to go to work.',story:'The Hot Rod Deluxe combined a substantial clean channel with additional drive options. Its single twelve-inch speaker kept the format familiar and portable. Later revisions continued the family, while retaining its basic role as a working tube combo.'},
 {year:2006,name:'Super-Sonic 60',era:'New voices',years:'2006–2010s, early series',watts:60,speakers:'1 × 12″',load:'8 Ω',finish:'cream',width:1.17,height:1.02,circuit:'Super-Sonic 60',voice:'Vintage roots. A different edge.',story:'The Super-Sonic paired vintage-inspired clean voices with a higher-gain channel. It gave Fender players another route through a modern tube amplifier. The family later expanded to include different power levels and cabinet configurations.'},
 {year:2016,name:'’57 Custom Deluxe',era:'Back to the workbench',years:'2016 onward',watts:12,speakers:'1 × 12″',load:'8 Ω',finish:'tweed',width:1,height:1,circuit:'Hand-wired 5E3-inspired',voice:'A circuit worth returning to.',story:'The ’57 Custom Deluxe revisited the small tweed combo with hand-wired construction. A twelve-watt rating and a single twelve-inch speaker preserved its compact scale. The modern interpretation shows how enduring the original Deluxe idea has become.'},
 {year:2021,name:'Custom Pro Reverb',era:'A lighter chapter',years:'2021 onward',watts:40,speakers:'1 × 12″',load:'8 Ω',finish:'silver',width:1.08,height:.95,circuit:'’68 Custom Pro Reverb',voice:'A big voice, a lighter footprint.',story:'The ’68 Custom Pro Reverb reworked the Pro idea as a single-channel, single-speaker combo. A lightweight speaker helped reduce the burden of a forty-watt tube amp. Its silver-panel appearance connects it to a different, larger vintage predecessor.'}
];

amps.splice(11,0,{year:1977,name:'Ultralinear Twin',era:'The headroom years',years:'1977–1982',watts:135,speakers:'2 × 12″',load:'4 Ω',finish:'silver',width:1.25,height:1.02,circuit:'Ultralinear Twin Reverb',voice:'Clean power for a larger stage.',story:'The late-1970s Twin Reverb increased its rated output to 135 watts with an ultralinear output stage. It continued the familiar two-speaker format while pushing further toward clean headroom. Its powerful, heavy design reflects a different set of priorities from the small tweed combos.'});
amps.push({year:1963,name:'Twin Reverb',era:'The black-panel years',years:'1963–1967',watts:85,speakers:'2 × 12″',load:'4 Ω',finish:'black',width:1.25,height:1.02,circuit:'AB763',voice:'The high-headroom reference.',story:'The black-panel Twin Reverb combined two twelve-inch speakers with spring reverb and tremolo. Its four 6L6 output tubes supplied substantial clean headroom. The Twin name continued into the silver-panel years, but those later versions need their own production and circuit context.'});
amps.sort((a,b)=>a.year-b.year||a.watts-b.watts||a.name.localeCompare(b.name));
function panelLabel(a){
 if(a.era==='The black-panel years')return 'Black panel';
 if(a.era==='The silver-panel years'||a.era==='The headroom years')return 'Silver panel';
 if(a.finish==='wood')return 'Woodie';
 if(a.year===1949)return 'Two-tone';
 if(a.finish==='brown')return 'Brown panel';
 if(a.era==='The Rivera years')return 'Rivera era';
 if(a.year===2016)return 'Tweed reissue';
 if(a.year===2021)return 'Modern silver style';
 if(a.year===1993)return 'Modern tweed style';
 if(a.year===1996)return 'Hot Rod series';
 if(a.year===2006)return 'Modern tube';
 return 'Tweed';
}
function cardLeft(card){return card.getBoundingClientRect().left-scroll.getBoundingClientRect().left+scroll.scrollLeft;}
function variant(a){return createAmpModel(a);}

const strip=$('amp-strip'),scroll=$('collection-scroll'),detail=$('amp-detail');let selected=null,returnFocus=null,savedScroll=0,savedY=0,paused=reduced;
const groups=new Map();
for(const a of amps){if(!groups.has(a.year))groups.set(a.year,[]);groups.get(a.year).push(a);}
const cards=[];
for(const [year,models] of groups){
 const group=document.createElement('div');group.className='year-group'+(models.length>1?' year-group-shared':'');group.dataset.year=year;group.setAttribute('role','group');group.setAttribute('aria-label',`Introduced in ${year}. ${models.length} ${models.length===1?'model':'models'}, ordered by wattage.`);
 const row=document.createElement('div');row.className='year-amps';group.append(row);
 for(const a of models){const i=amps.indexOf(a),b=document.createElement('button');b.className='amp-card';b.dataset.watts=a.watts;b.dataset.panel=panelLabel(a);b.setAttribute('aria-label',`${a.year} ${a.name}, ${panelLabel(a)}, ${a.watts} watts. Open amplifier detail`);b.innerHTML=`<span class="amp-slot" aria-hidden="true"></span><span class="amp-tether" aria-hidden="true"></span><strong>${a.name}</strong><span class="amp-card-meta">${a.watts} W <i> / </i> ${a.speakers}</span><span class="amp-era" data-finish="${a.finish}">${panelLabel(a)}</span><span class="amp-open">Explore the amp</span>`;b.onclick=()=>openAmp(i,b);row.append(b);cards.push(b);}
 const branch=document.createElement('span');branch.className='year-branches';branch.setAttribute('aria-hidden','true');group.append(branch);
 const stem=document.createElement('span');stem.className='year-stem';stem.setAttribute('aria-hidden','true');group.append(stem);
 const marker=document.createElement('div');marker.className='year-marker';marker.innerHTML=`<span>${year}</span>${models.length>1?`<small>${models.length} models</small>`:''}`;group.append(marker);strip.append(group);
}
document.querySelector('.collection-note').innerHTML=`${amps.length} selected models. <a href="components.html">Explore the component library</a>. <button id="era-guide">Panel eras explained</button>`;
$('era-guide').onclick=()=>{const d=$('dialog');$('dialog-content').innerHTML='<span class="eyebrow">READING THE COLLECTION</span><h2>One name. Different generations.</h2><p>Black panel and silver panel describe the amplifier’s control panel, not the grille cloth or cabinet covering. Blackface and silverface are the familiar historical terms for these eras.</p><p>A model that spans both eras appears as separate entries. Circuit changes did not always coincide with a cosmetic change, so early silver-panel amps can retain earlier circuitry. Major revisions, such as the 135-watt ultralinear Twin, receive their own entry.</p><p>Modern amplifiers styled after an earlier era are labeled as modern designs or reissues. Their timeline year is their own introduction, not the vintage year in their product name.</p><p>Years mark approximate introductions, rather than the build date of a photographed example. Surviving transitional examples can overlap.</p><p><a href="https://www.fender.com/articles/parts-and-accessories/tweed-tolex-two-tone-a-guide-to-amp-coverings" target="_blank" rel="noopener noreferrer">Fender’s guide to amplifier coverings and panel eras</a></p>' ;d.showModal();};
const decadeValues=[1940,1950,1960,1970,1980,1990,2000,2010,2020];
decadeValues.forEach(d=>{const b=document.createElement('button');b.textContent=`${d}s`;b.dataset.decade=d;b.onclick=()=>{const i=amps.findIndex(a=>a.year>=d);scrollToIndex(i<0?amps.length-1:i)};$('collection-decades').append(b);});
function scrollToIndex(i){scroll.scrollTo({left:cardLeft(cards[Math.max(0,i)]),behavior:reduced?'instant':'smooth'});}
function positionSharedMarkers(){
 const viewport=scroll.getBoundingClientRect();
 for(const group of document.querySelectorAll('.year-group-shared')){
  const bounds=group.getBoundingClientRect();const start=Math.max(viewport.left,bounds.left),end=Math.min(viewport.right,bounds.right);
  if(end-start<90)continue;
  const half=group.querySelector('.amp-card').getBoundingClientRect().width/2;
  const center=Math.max(half,Math.min(bounds.width-half,(start+end)/2-bounds.left));
  group.querySelector('.year-marker').style.left=`${center}px`;group.querySelector('.year-stem').style.left=`${center}px`;
 }
}
function updatePosition(){positionSharedMarkers();const left=scroll.scrollLeft;const visible=cards.map((b,i)=>({i,left:cardLeft(b),right:cardLeft(b)+b.offsetWidth})).filter(b=>Math.min(b.right,left+scroll.clientWidth)-Math.max(b.left,left)>cards[b.i].offsetWidth*.5);const first=amps[visible[0]?.i||0];const last=amps[visible.at(-1)?.i||0];$('collection-position').textContent=`${first.year} — ${last.year}`;const max=scroll.scrollWidth-scroll.clientWidth;const progress=max?left/max:0;$('collection-progress').firstElementChild.style.transform=`translateX(${progress*200}%)`;$('collection-previous').disabled=left<2;$('collection-next').disabled=left>=max-2;document.querySelectorAll('#collection-decades button').forEach(b=>{const current=+b.dataset.decade===Math.floor(first.year/10)*10;b.classList.toggle('active',current);b.setAttribute('aria-pressed',current)});}
scroll.addEventListener('scroll',updatePosition,{passive:true});new ResizeObserver(updatePosition).observe(scroll);
scroll.addEventListener('wheel',e=>{if(e.ctrlKey||Math.abs(e.deltaX)>Math.abs(e.deltaY))return;const max=scroll.scrollWidth-scroll.clientWidth;if(max<=0)return;if((e.deltaY>0&&scroll.scrollLeft<max-1)||(e.deltaY<0&&scroll.scrollLeft>1)){e.preventDefault();scroll.scrollLeft+=e.deltaY;}},{passive:false});
scroll.addEventListener('keydown',e=>{if(e.target!==scroll)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();scroll.scrollBy({left:(e.key==='ArrowRight'?1:-1)*cards[0].offsetWidth,behavior:reduced?'instant':'smooth'});}});
let drag=null;scroll.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;drag={x:e.clientX,left:scroll.scrollLeft,moved:false};});scroll.addEventListener('pointermove',e=>{if(!drag)return;if(Math.abs(e.clientX-drag.x)>6){drag.moved=true;scroll.classList.add('dragging');scroll.scrollLeft=drag.left-(e.clientX-drag.x);}});window.addEventListener('pointerup',()=>{setTimeout(()=>{drag=null;scroll.classList.remove('dragging')},0)});scroll.addEventListener('click',e=>{if(drag?.moved){e.preventDefault();e.stopImmediatePropagation()}},true);
$('collection-previous').onclick=()=>scroll.scrollBy({left:-scroll.clientWidth*.8,behavior:reduced?'instant':'smooth'});$('collection-next').onclick=()=>scroll.scrollBy({left:scroll.clientWidth*.8,behavior:reduced?'instant':'smooth'});
function updateMotion(){$('collection-motion').textContent=paused?'Resume motion':'Pause motion';$('collection-motion').setAttribute('aria-pressed',!paused);}$('collection-motion').onclick=()=>{paused=!paused;updateMotion()};updateMotion();

const originalStory=$('story-content').innerHTML,originalSpecs=$('specs-content').innerHTML,originalSource=$('sources').onclick;
function openAmp(i,button){if(drag?.moved)return;const a=amps[i];selected=i;returnFocus=button;savedScroll=scroll.scrollLeft;savedY=window.scrollY;
 $('collection').inert=true;document.querySelector('.masthead').inert=true;document.querySelector('.site-footer').inert=true;
 detail.hidden=false;document.title=`${a.name} (${panelLabel(a)}) — The Amplifier Observatory`;$("viewport").setAttribute("aria-label",`Interactive 3D ${a.name} cabinet study. Drag to rotate, scroll to zoom.`);detail.querySelector(".exhibit").setAttribute("aria-label",`${a.name} interactive exhibit`);document.body.classList.add('detail-open');$('detail-index').textContent=`${a.year} / ${a.name.toUpperCase()} / ${panelLabel(a).toUpperCase()}`;detail.setAttribute('aria-label',`${a.name}, ${panelLabel(a)} amplifier detail`);
 detail.querySelector('.stage-top .eyebrow').innerHTML=`<i></i> ${a.era.toUpperCase()}`;detail.querySelector('.object-id').textContent=`FENDER / ${a.circuit.toUpperCase()} / ${a.year}`;
 detail.querySelector('.story-panel > .eyebrow').innerHTML=`${a.years} <span class="tag">${panelLabel(a).toUpperCase()}</span>`;const words=a.name.split(' ');detail.querySelector('h1').innerHTML=`${words.slice(0,-1).join(' ')}<br><em>${words.at(-1)}.</em>`;detail.querySelector('.deck').textContent=a.voice;
 $('story-content').innerHTML=a.full?originalStory:`<p>${a.story}</p><div class="quote-note"><span>THE ERA</span><strong>${a.era}</strong></div>`;
 $('specs-content').innerHTML=a.full?originalSpecs:`<dl class="details"><div><dt>Panel / era</dt><dd>${panelLabel(a)}</dd></div><div><dt>Circuit / version</dt><dd>${a.circuit}</dd></div><div><dt>Production</dt><dd>${a.years}</dd></div><div><dt>Format</dt><dd>Tube combo</dd></div><div><dt>Speaker layout</dt><dd>${a.speakers}</dd></div></dl><p class="fine">Representative specifications. Cabinet profiles distinguish top and front controls, speaker layouts and finishes; internal components are illustrative. ${a.ratingNote||''}</p>`;
 const dds=detail.querySelectorAll('.spec-grid dd');dds[0].innerHTML=`${a.watts}<span> W</span>`;dds[1].textContent=a.speakers;dds[2].textContent=a.load;
 detail.querySelector('.panel-footer > span').textContent=a.circuit.toUpperCase();detail.querySelector('.model-note').textContent=a.full?'INTERPRETIVE 3D RECREATION':'REPRESENTATIVE CABINET STUDY';detail.querySelector('.object-caption strong').textContent=a.full?'OUTSIZED INFLUENCE.':a.era.toUpperCase();detail.querySelector('.object-caption span:last-child').firstChild.textContent=a.full?'SMALL CABINET.':'FENDER TUBE AMPLIFIERS.';
 $('sources').onclick=a.full?originalSource:()=>{const d=$('dialog');$('dialog-content').innerHTML=`<span class="eyebrow">EXHIBIT NOTES</span><h2>${a.name}</h2><p>${a.story}</p><p>These are representative catalog specifications, with rounded output ratings. Production transitions and surviving examples vary. The 3D cabinet is an interpretive study, not a scan or an exact component layout.</p><p><a href="https://support.fender.com/hc/en-us/articles/47450512831259-Fender-Guitar-Amplifier-Owner-s-Manuals" target="_blank" rel="noopener noreferrer">Fender’s official owner manual archive</a></p>`;d.showModal()};
 const reference=modelReference(a);if(reference){const baseSource=$('sources').onclick;$('sources').onclick=()=>{baseSource();$('dialog-content').innerHTML+=`<p><a href="${reference.source}" target="_blank" rel="noopener noreferrer">Exterior reference: ${reference.name}</a></p><p>${reference.basis||'Cabinet dimensions use current reissue specifications as a family proxy, rather than a measured vintage cabinet.'} Badges, cloth and detail dimensions remain interpretive.</p>`;};$('specs-content').innerHTML+=`<dl class="details"><div><dt>Cabinet W × H × D</dt><dd>${reference.dimensions}</dd></div></dl><p class="fine">${reference.basis||'Modern reissue dimension proxy; vintage measurements pending'}. Rear components are illustrative.</p>`;detail.querySelector('.model-note').textContent='REFINED CABINET STUDY';} const assembly=assemblyFor(a);if(assembly){$('specs-content').innerHTML+=`<dl class="details"><div><dt>Speaker reference</dt><dd>${assembly.speakerCount} × ${assetById(assembly.speaker).name}</dd></div><div><dt>Speaker wiring</dt><dd>${assembly.wiring}</dd></div><div><dt>Reference example</dt><dd>${assembly.example}</dd></div></dl><p class="fine">Speaker geometry and finishes remain under review. <a href="components.html">Inspect the shared component library</a>.</p>`;detail.querySelector('.model-note').textContent='COMPONENT LIBRARY / REFERENCE ASSEMBLY';} $('story-tab').click();detail.scrollTop=0;detailScene?.showModel(variant(a));detailScene?.setVisible(true);$('close-detail').focus({preventScroll:true});
}
function closeAmp(){if(selected===null)return;if($('dialog').open){$('dialog').close();return;}if(document.fullscreenElement){document.exitFullscreen();}detailScene?.setVisible(false);detail.hidden=true;document.title="The Amplifier Observatory — The collection";document.body.classList.remove('detail-open');$('collection').inert=false;document.querySelector('.masthead').inert=false;document.querySelector('.site-footer').inert=false;scroll.scrollLeft=savedScroll;window.scrollTo({top:savedY,behavior:'instant'});returnFocus?.focus({preventScroll:true});selected=null;}
$('close-detail').onclick=closeAmp;
document.addEventListener('keydown',e=>{if(detail.hidden||$('dialog').open)return;if(e.key==='Escape'){e.preventDefault();closeAmp();return;}if(e.key==='Tab'){const focusable=[...detail.querySelectorAll('button,[tabindex="0"],a')].filter(el=>!el.disabled&&el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('about').onclick=()=>{$('dialog-content').innerHTML='<span class="eyebrow">THE AMPLIFIER OBSERVATORY</span><h2>A collection to move through.</h2><p>Explore twenty-two selected Fender tube amplifier models from the earliest wooden cabinets to modern interpretations. Scroll through the collection, jump to a decade, or select an amp to open its story.</p><p>This is a 22-entry selection from a roughly 200-entry catalog. The tweed Deluxe, Deluxe Reverb and Twin Reverb cabinet families have refined exterior proportions and controls. Other entries remain representative cabinet studies. The full catalog will expand by model generation, with individually checked cabinets and details. Closing an exhibit returns you to your place in the collection.</p><p>An independent prototype, not affiliated with Fender Musical Instruments Corporation.</p>';$('dialog').showModal()};

if(detailScene){const host=$('collection-render');try{const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setClearColor(0x090c10,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.45;host.append(renderer.domElement);
 const collectionEnvironment=studioEnvironment(renderer);const scenes=amps.map((a,i)=>{const scene=new THREE.Scene();scene.environment=collectionEnvironment.texture;scene.environmentIntensity=.55;const model=variant(a);scene.add(model);scene.add(new THREE.HemisphereLight(0xc8dae6,0x4a3020,2.4));for(const [color,power,pos] of [[0xffdfab,4.2,[-4,6,5]],[0xabcce8,2.4,[5,3,-4]],[0xffffff,1,[0,2,7]]]){const light=new THREE.DirectionalLight(color,power);light.position.set(...pos);scene.add(light)}const camera=new THREE.PerspectiveCamera(34,1,.1,50);camera.position.set(4.5,2.8,10);camera.lookAt(0,.05,0);return{scene,model,camera,slot:cards[i].querySelector('.amp-slot')};});
 const resize=()=>renderer.setSize(host.clientWidth,host.clientHeight);new ResizeObserver(resize).observe(host);resize();let last=0;let phase=0;
 function frame(time){requestAnimationFrame(frame);if(document.hidden||selected!==null){last=time;return;}if(time-last<32)return;const dt=Math.min((time-last)/1000,.1);last=time;if(!paused)phase+=dt;const root=host.getBoundingClientRect();renderer.setScissorTest(false);renderer.clear();renderer.setScissorTest(true);for(let i=0;i<scenes.length;i++){const s=scenes[i],r=s.slot.getBoundingClientRect();if(r.right<=root.left||r.left>=root.right)continue;const x=r.left-root.left,y=root.bottom-r.bottom,w=r.width,h=r.height;renderer.setViewport(x,y,w,h);renderer.setScissor(Math.max(0,x),Math.max(0,y),Math.min(w,root.width-Math.max(0,x),r.right-root.left),Math.min(h,root.height-y));s.camera.aspect=w/h;s.camera.updateProjectionMatrix();s.model.rotation.y=-.35+Math.sin(phase*.17+i*.6)*.48;s.model.position.y=paused?0:Math.sin(phase*.6+i)*.055;renderer.render(s.scene,s.camera);}renderer.setScissorTest(false);}requestAnimationFrame(frame);
 }catch(error){console.error(error);host.innerHTML='<p class="render-error">3D rendering is unavailable in this browser. You can still select an amp to read its story.</p>';}}
updatePosition();

// Review link uses the same entry/close behavior as a timeline selection.
const exhibitQuery=new URLSearchParams(location.search);
const reviewAmps={'twin-1968':{year:1968,name:'Twin Reverb'},'deluxe-reverb-1965':{year:1963,name:'Deluxe Reverb'},'champ-1959':{year:1958,name:'Tweed Champ'},'tremolux-1955':{year:1955,name:'Tweed Tremolux'},'deluxe-1962':{year:1961,name:'Brown Deluxe'}};
const reviewAmp=reviewAmps[exhibitQuery.get('amp')];
if(reviewAmp){const i=amps.findIndex(a=>a.year===reviewAmp.year&&a.name===reviewAmp.name);if(i>=0){openAmp(i,cards[i]);if(exhibitQuery.get('view')==='inside')$('rear').click();}}
